edits.newText:
When('I clear the edit input and press Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  // Dispatch an input event so the app's blur listener on the edit input fires
  // before the keydown Enter, ensuring editingId is reset and the todo is removed.
  const editInput = editing.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

